<?php
if (!current_user_is_at_least_admin()) { echo '<div class="alert alert-danger">Acesso negado.</div>'; return; }
$mes = date('m'); $ano = date('Y');
$stmt = $pdo->prepare("SELECT COALESCE(SUM(CASE WHEN tipo='receita' AND status='pago' THEN valor ELSE 0 END),0) receitas, COALESCE(SUM(CASE WHEN tipo='despesa' AND status='pago' THEN valor ELSE 0 END),0) despesas, COALESCE(SUM(CASE WHEN status='pendente' THEN valor ELSE 0 END),0) pendentes FROM fin_lancamentos_caixa WHERE MONTH(data_movimento)=? AND YEAR(data_movimento)=?");
$stmt->execute([$mes,$ano]); $resumo = $stmt->fetch(PDO::FETCH_ASSOC);
$saldoMes = (float)$resumo['receitas']-(float)$resumo['despesas'];
$contas = $pdo->query("SELECT c.*, COALESCE(SUM(CASE WHEN l.status='pago' AND l.tipo='receita' THEN l.valor WHEN l.status='pago' AND l.tipo='despesa' THEN -l.valor ELSE 0 END),0) saldo FROM fin_contas c LEFT JOIN fin_lancamentos_caixa l ON l.conta_id=c.id WHERE c.status='ativo' GROUP BY c.id ORDER BY c.nome")->fetchAll();
$recentes = $pdo->query("SELECT l.*,c.nome conta_nome,cat.nome categoria_nome FROM fin_lancamentos_caixa l JOIN fin_contas c ON c.id=l.conta_id JOIN fin_categorias cat ON cat.id=l.categoria_id ORDER BY l.data_movimento DESC,l.id DESC LIMIT 8")->fetchAll();
$stmt = $pdo->prepare("SELECT cat.nome,cat.cor,SUM(l.valor) total FROM fin_lancamentos_caixa l JOIN fin_categorias cat ON cat.id=l.categoria_id WHERE l.tipo='despesa' AND l.status='pago' AND MONTH(l.data_movimento)=? AND YEAR(l.data_movimento)=? GROUP BY cat.id ORDER BY total DESC LIMIT 8");
$stmt->execute([$mes,$ano]); $categorias=$stmt->fetchAll(); $baseHref=BASE_URL.'index.php';
?>
<div class="container-fluid py-4">
 <div class="card border-0 shadow-sm rounded-4 p-4 mb-4 text-white" style="background:linear-gradient(135deg,#0f172a,#0f766e)"><div class="d-flex flex-wrap justify-content-between align-items-center gap-3"><div><h2 class="fw-bold mb-1"><i class="bi bi-wallet2 me-2"></i>Financeiro</h2><p class="mb-0 opacity-75">Contas, caixa, cartões e resultados em um só lugar.</p></div><a href="<?php echo $baseHref;?>?m=fin_lancamentos_caixa&a=form" class="btn btn-light fw-semibold"><i class="bi bi-plus-circle me-1"></i>Novo lançamento</a></div></div>
 <div class="row g-3 mb-4">
 <?php foreach([['Receitas do mês',$resumo['receitas'],'success','arrow-up-circle'],['Despesas do mês',$resumo['despesas'],'danger','arrow-down-circle'],['Saldo do mês',$saldoMes,$saldoMes>=0?'primary':'danger','graph-up'],['Pendências',$resumo['pendentes'],'warning','clock-history']] as $card):?>
  <div class="col-12 col-sm-6 col-xl"><div class="card border-0 shadow-sm h-100"><div class="card-body"><div class="text-muted small"><i class="bi bi-<?php echo $card[3];?> me-1"></i><?php echo $card[0];?></div><div class="fs-4 fw-bold text-<?php echo $card[2];?> mt-2">R$ <?php echo number_format((float)$card[1],2,',','.');?></div></div></div></div>
 <?php endforeach;?></div>
 <div class="row g-3 mb-4">
 <?php foreach([['fin_contas','Contas','bank'],['fin_categorias','Categorias','tags'],['fin_lancamentos_caixa','Lançamentos de caixa','cash-stack']] as $item):?>
  <div class="col-12 col-md-6 col-xl"><a href="<?php echo $baseHref;?>?m=<?php echo $item[0];?>&a=list" class="card border-0 shadow-sm h-100 text-decoration-none"><div class="card-body d-flex align-items-center gap-3"><i class="bi bi-<?php echo $item[2];?> fs-3 text-primary"></i><span class="fw-semibold text-dark"><?php echo $item[1];?></span></div></a></div>
 <?php endforeach;?></div>
 <div class="row g-4"><div class="col-12 col-xl-8"><div class="card border-0 shadow-sm"><div class="card-header bg-white border-0 pt-3 d-flex justify-content-between"><h5 class="fw-bold">Lançamentos recentes</h5><a href="<?php echo $baseHref;?>?m=fin_lancamentos_caixa&a=list">Ver todos</a></div><div class="table-responsive"><table class="table align-middle mb-0"><thead class="table-light"><tr><th>Data</th><th>Descrição</th><th>Conta</th><th>Categoria</th><th class="text-end">Valor</th></tr></thead><tbody>
 <?php if(!$recentes):?><tr><td colspan="5" class="text-center text-muted py-4">Nenhum lançamento.</td></tr><?php endif;?>
 <?php foreach($recentes as $row):?><tr><td><?php echo date('d/m/Y',strtotime($row['data_movimento']));?></td><td><?php echo htmlspecialchars($row['descricao']);?></td><td><?php echo htmlspecialchars($row['conta_nome']);?></td><td><?php echo htmlspecialchars($row['categoria_nome']);?></td><td class="text-end fw-bold text-<?php echo $row['tipo']==='receita'?'success':($row['tipo']==='despesa'?'danger':'primary');?>">R$ <?php echo number_format((float)$row['valor'],2,',','.');?></td></tr><?php endforeach;?></tbody></table></div></div></div>
 <div class="col-12 col-xl-4"><div class="card border-0 shadow-sm mb-4"><div class="card-body"><h5 class="fw-bold mb-3">Saldos das contas</h5><?php foreach($contas as $conta):?><div class="d-flex justify-content-between border-bottom py-2"><span><?php echo htmlspecialchars($conta['nome']);?></span><strong>R$ <?php echo number_format((float)$conta['saldo'],2,',','.');?></strong></div><?php endforeach;?><?php if(!$contas):?><span class="text-muted">Nenhuma conta ativa.</span><?php endif;?></div></div><div class="card border-0 shadow-sm"><div class="card-body"><h5 class="fw-bold mb-3">Despesas por categoria</h5><?php foreach($categorias as $cat):?><div class="d-flex justify-content-between border-bottom py-2 small"><span><?php echo htmlspecialchars($cat['nome']);?></span><strong>R$ <?php echo number_format((float)$cat['total'],2,',','.');?></strong></div><?php endforeach;?><?php if(!$categorias):?><span class="text-muted">Sem despesas no mês.</span><?php endif;?></div></div></div></div>
</div>
